<script setup lang="ts">
import { posts } from '../data/scanPosts'
import { Divider } from 'animal-island-vue'

// 建站起始日期（用于计算建站天数）
const siteStart = new Date('2020-01-01')

// 文章数量
const articleCount = posts.length

// 累计字数：扫描所有 md 正文（去掉 frontmatter）的中文字符数
const wordCount = (() => {
  const modules = import.meta.glob('../../../../**/*.md', {
    eager: true,
    query: '?raw',
    import: 'default'
  }) as Record<string, string>
  let total = 0
  for (const path in modules) {
    if (/(^|\/)(index|about|links)\.md$/.test(path)) continue
    const raw = modules[path] || ''
    const body = raw.replace(/^---[\s\S]*?---/, '')
    const cn = body.match(/[一-龥]/g)
    if (cn) total += cn.length
  }
  return total
})()

// 建站天数
const days = Math.floor((Date.now() - siteStart.getTime()) / 86400000)

// 微信二维码弹窗
// 社交链接
